import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"剝","description":"周易集解 - 剝","frontmatter":{"title":"剝","description":"周易集解 - 剝"},"headers":[],"relativePath":"zh/classics/jijie/023.md","filePath":"zh/classics/jijie/023.md"}'),l={name:"zh/classics/jijie/023.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="剝" tabindex="-1">剝 <a class="header-anchor" href="#剝" aria-label="Permalink to “剝”">​</a></h1><h2 id="剝-1" tabindex="-1">剝 <a class="header-anchor" href="#剝-1" aria-label="Permalink to “剝”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>剝，不利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：致飾然後通則盡矣，故受之以剝。剝者，剝也。</p><p>崔憬曰：以文致飾，則上下情通，故曰｢致飾然後通｣也。文者致理，極而無救則盡矣。盡，猶剝也。</p><p>虞翻曰：陰消乾也，與夬旁通。以柔變剛，小人道長；子弒其父，臣弒其君，故不利有攸往也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：剝，剝也。柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>盧氏曰：此本乾卦。群陰剝陽，故名為剝也。</p><p>荀爽曰：謂陰外變五。五者至尊，為陰所變，故曰剝也。</p><p>鄭玄曰：陰氣侵陽，上至於五，萬物零落，故謂之剝也。五陰一陽，小人極盛，君子不可有所之，故不利有攸往也。</p><p>虞翻曰：坤順艮止，謂五消觀成剝，故觀象也。</p><p>虞翻曰：乾為君子，乾息為盈，坤消為虛，故｢君子尚消息盈虛，天行也｣。則出入無疾，反覆其道。易虧巽消艮，出震息兌，盈乾虛坤，故於是見之耳。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山附於地，剝。上以厚下安宅。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>陸績曰：艮為山，坤為地。山附於地，謂高附於卑，貴附於賤，君不能制臣也。</p><p>虞翻曰：上，君也。宅，居也。山高絕於地。今附地者，明被剝矣。屬地時也。君當厚錫於下，賢當卑降於愚，然後得安其居。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，剝牀以足，蔑貞凶。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：此卦坤變乾也。動初成巽，巽木為牀；復震在下，為足，故｢剝牀以足｣。蔑，無。貞，正也。失位無應，故蔑貞凶。震在陰下，《象》曰：以滅下也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：剝牀以足，以滅下也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：蔑，滅也。坤所以載物，牀所以安人。在下，故稱足。先從下剝，漸及於上，則君政崩滅。故曰以滅下也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，剝牀以辯，蔑貞凶。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：指間稱辯剝。剝二成艮。艮為指，二在指間。故｢剝牀以辯｣。無應在剝，故蔑貞凶也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：剝牀以辯，未有與也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>鄭玄曰：足上稱辯，謂近膝之下。屈則相近，申則相遠，故謂之辯。辯，分也。</p><p>崔憬曰：今以牀言之，則辯當在第足之間，是牀梐也。｢未有與｣者，言至三則應，故二未有與也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，剝之無咎。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：剝之無咎，失上下也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：眾皆剝陽，三獨應上，無剝害意，是以無咎。故曰：失上下也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，剝牀以膚，凶。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：辯上稱膚。艮為膚。以陰變陽，至四乾毀，故｢剝牀以膚｣。臣弒君，子弒父，故凶矣。</p><p>王肅曰：在下而安人者，牀也。在上而處牀者，人也。坤以象牀，艮以象人。牀剝盡，以及人身，為敗滋深，害莫甚焉。故曰｢剝牀以膚，凶｣也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：剝牀以膚，切近災也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：牀之膚謂薦席，若獸之有皮毛也。牀以剝盡，次及其膚，剝以大臣之象，言近身與君也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，貫魚，以宮人寵，無不利。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：剝消觀五。巽為魚，為繩；艮手持繩貫巽，故貫魚也。艮為宮室，人謂乾；五以陰代陽，五貫乾，為寵人，陰得麗之，故以宮人寵。動得正成觀，故無不利也。</p><p>何妥曰：夫剝之為卦，下比五陰，駢頭相次，似貫魚也。魚為陰物，以喻眾陰也。夫宮人者，後夫人嬪妾，各有次序，不相瀆亂，此則貴賤有章，寵御有序。六五既為眾陰之主，能有貫魚之次第，故得無不利矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：以宮人寵，終無尤也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：魚與宮人皆陰類，以比小人焉。魚大小一貫，若後夫人嬪婦御女，小大雖殊，寵御則一，故終無尤也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，碩果不食。君子得輿，小人剝廬。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：艮為碩果，謂三已複位，有頤象。頤中無物，故不食也。夬乾為君子，為德；坤為車，為民；乾在坤，故以德為車。小人謂坤，艮為廬；上變滅艮，坤陰迷亂，故小人剝廬也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子得輿，民所載也。小人剝廬，終不可用也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：艮為果，為廬。坤為輿。處剝之上，有剛直之德，群小人不能傷害也。故果至碩大，不被剝食矣。君子居此，萬姓賴安，若得乘其車輿也。小人處之，則庶方無控，被剝其廬舍，故曰｢剝廬，終不可用｣矣。</p>',70)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
